-- Native Webflow Cloud SQLite (D1). No remote migration has been deployed yet.
-- IDs are generated by the server; timestamps are UTC ISO-8601 strings.
-- D1 has no PostgreSQL RLS: access goes through authorized server repositories.
CREATE TABLE app_schema_versions (
  version TEXT PRIMARY KEY NOT NULL,
  applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE users (
  id TEXT PRIMARY KEY NOT NULL,
  disabled_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE organizations (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 160),
  timezone TEXT NOT NULL DEFAULT 'America/Sao_Paulo',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE memberships (
  organization_id TEXT NOT NULL REFERENCES organizations(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  role TEXT NOT NULL CHECK (role IN ('OWNER','MANAGER','TECHNICAL','COMMERCIAL','FINANCE')),
  revoked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (organization_id, user_id)
);

CREATE TABLE professionals (
  id TEXT PRIMARY KEY NOT NULL,
  organization_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  display_name TEXT NOT NULL CHECK (length(trim(display_name)) BETWEEN 1 AND 160),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, user_id),
  FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id)
);

CREATE TABLE students (
  id TEXT PRIMARY KEY NOT NULL,
  organization_id TEXT NOT NULL REFERENCES organizations(id),
  display_name TEXT NOT NULL CHECK (length(trim(display_name)) BETWEEN 1 AND 160),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (organization_id, id)
);

CREATE TABLE care_assignments (
  organization_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  professional_id TEXT NOT NULL,
  revoked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (organization_id, student_id, professional_id),
  FOREIGN KEY (organization_id, student_id) REFERENCES students(organization_id, id),
  FOREIGN KEY (organization_id, professional_id) REFERENCES professionals(organization_id, id)
);

CREATE TABLE student_access (
  organization_id TEXT NOT NULL,
  student_id TEXT NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id),
  revoked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (organization_id, student_id, user_id),
  FOREIGN KEY (organization_id, student_id) REFERENCES students(organization_id, id)
);

CREATE INDEX memberships_user_idx ON memberships(user_id, organization_id);
CREATE INDEX student_access_user_idx ON student_access(user_id, organization_id);
CREATE INDEX care_assignments_professional_idx ON care_assignments(organization_id, professional_id);

